/* ===== round 11f: hall backgrounds by federation tier (AI-generated art, supplied by the author) ===== */
const HALL_SRC={1:'data:image/webp;base64,',2:'data:image/webp;base64,',3:'data:image/webp;base64,',4:'data:image/webp;base64,',5:'data:image/webp;base64,'};

Object.assign(D,{'hall.title':['Tła hal','Hall backgrounds'],'hall.on':['Tła hal włączone','Hall backgrounds on'],'hall.off':['Tła hal wyłączone','Hall backgrounds off'],'hall.dim':['Przyciemnienie tła','Background dimming']});
const LS_HALL='ringboss.hall.v1';
const HALL={on:true,dim:.78};
try{const s=JSON.parse(localStorage.getItem(LS_HALL)||'null');if(s){HALL.on=s.on!==false;HALL.dim=typeof s.dim==='number'?Math.min(.95,Math.max(.5,s.dim)):.78}}catch(e){}
function hallSave(){try{localStorage.setItem(LS_HALL,JSON.stringify({on:HALL.on,dim:HALL.dim}))}catch(e){}}
function hallApply(){if(typeof document==='undefined')return;let el=document.getElementById('hallbg');
 if(!el){el=document.createElement('div');el.id='hallbg';document.body.insertBefore(el,document.body.firstChild)}
 const tr=(typeof G!=='undefined'&&G&&G.fed)?Math.min(5,Math.max(1,G.fed.tier|0||1)):0;
 if(!HALL.on||!tr){el.style.display='none';return}
 el.style.display='block';
 if(el.dataset.t!==String(tr)){el.dataset.t=String(tr);el.style.backgroundImage='url('+HALL_SRC[tr]+')'}
 el.style.setProperty('--hd',HALL.dim)}
(function(){const css=document.createElement('style');css.textContent='#hallbg{position:fixed;inset:0;z-index:0;background-size:cover;background-position:center bottom;pointer-events:none}#hallbg::after{content:"";position:absolute;inset:0;background:rgba(8,8,12,var(--hd,.78))}#app{position:relative;z-index:1}';document.head.appendChild(css)})();
(function(){const _r=render;render=function(){const r=_r.apply(this,arguments);try{hallApply()}catch(e){}return r}})();
Object.assign(CHG,{halldim(e){HALL.dim=+e.value/100;hallSave();hallApply()}});
ACT.halltog=function(){HALL.on=!HALL.on;hallSave();render()};
(function(){const _vs=vSettings;vSettings=function(){const h=_vs.apply(this,arguments);
 return h+'<div class="card stack"><h3>'+t('hall.title')+'</h3><div class="row" style="gap:12px;flex-wrap:wrap;align-items:center"><button class="btn'+(HALL.on?' gold':'')+'" data-act="halltog">'+t(HALL.on?'hall.on':'hall.off')+'</button><label class="row" style="gap:8px;align-items:center">'+t('hall.dim')+' <input type="range" min="50" max="95" value="'+Math.round(HALL.dim*100)+'" data-chg="halldim"></label></div></div>'};
})();
if(typeof normTexts==='function')normTexts();
